<template>
  <div class="flex flex-col gap-2 w-full">
    <div ref="containerRef" class="w-full h-full relative border">
      <AppLoader v-if="imageStatus === 'pending'" variant="inline" subject="petition image" />
      <AppError
        v-else-if="imageStatus === 'error'"
        title=""
        message="Failed to load petition template image"
        :action-text="null"
      />
      <v-stage ref="stageRef" :config="stageConfig">
        <v-layer>
          <v-image :config="imageConfig" />
        </v-layer>
        <v-layer>
          <v-group
            v-for="table in tables"
            :key="table.id"
            :config="{ x: table.x, y: table.y, draggable: false, name: table.id }"
          >
            <v-rect :config="{ width: table.w, height: table.h, stroke: 'blue', strokeWidth: 2, ...commonConfig }" />
            <v-label v-if="labelsConfig.visible" :config="{ x: 4, y: 4 }">
              <v-tag
                :config="{
                  fill: 'rgba(255,255,255,0.8)',
                  stroke: 'gray',
                  strokeWidth: 1,
                  cornerRadius: 3,
                  padding: labelsConfig.padding,
                  ...commonConfig,
                }"
              />
              <v-text
                :config="{
                  text: table.label || 'No Label',
                  fontSize: labelsConfig.fontSize,
                  fill: 'black',
                  padding: labelsConfig.padding,
                  ...commonConfig,
                }"
              />
            </v-label>
            <v-group
              v-for="row in table.rows"
              :key="row.id"
              :config="{ x: row.x, y: row.y, draggable: false, name: row.id }"
            >
              <v-rect :config="{ width: row.w, height: row.h, stroke: 'green', strokeWidth: 2, ...commonConfig }" />
              <v-label v-if="labelsConfig.visible" :config="{ x: 4, y: 4 }">
                <v-tag
                  :config="{
                    fill: 'rgba(255,255,255,0.8)',
                    stroke: 'gray',
                    strokeWidth: 1,
                    cornerRadius: 3,
                    padding: labelsConfig.padding,
                    ...commonConfig,
                  }"
                />
                <v-text
                  :config="{
                    text: row.label || 'No Label',
                    fontSize: labelsConfig.fontSize,
                    fill: 'black',
                    padding: labelsConfig.padding,
                    ...commonConfig,
                  }"
                />
              </v-label>
              <v-group
                v-for="sig in row.sigs"
                :key="sig.id"
                :config="{ x: sig.x, y: sig.y, draggable: false, name: sig.id }"
              >
                <v-rect :config="{ width: sig.w, height: sig.h, stroke: 'orange', strokeWidth: 2, ...commonConfig }" />
                <v-label v-if="labelsConfig.visible" :config="{ x: 4, y: 4 }">
                  <v-tag
                    :config="{
                      fill: 'rgba(255,255,255,0.8)',
                      stroke: 'gray',
                      strokeWidth: 1,
                      cornerRadius: 3,
                      padding: labelsConfig.padding,
                      ...commonConfig,
                    }"
                  />
                  <v-text
                    :config="{
                      text: sig.label || 'No Label',
                      fontSize: labelsConfig.fontSize,
                      fill: 'black',
                      padding: labelsConfig.padding,
                      ...commonConfig,
                    }"
                  />
                </v-label>
              </v-group>
            </v-group>
          </v-group>
        </v-layer>
      </v-stage>
    </div>
  </div>
</template>

<script setup lang="ts">
import type { BallotTemplatePageOutput } from '~/client';
import Konva from 'konva';
import type { TableModel } from '~/types/projects/labeling';

interface Props {
  page: BallotTemplatePageOutput;
}

const props = defineProps<Props>();

const containerRef = ref<HTMLElement | null>(null);
const stageRef = ref<Konva.Stage | null>(null);
const natural = reactive({ width: 0, height: 0 });
const stageConfig = reactive<Konva.StageConfig>({ width: 0, height: 0 });
const imageElem = ref<HTMLImageElement | null>(null);
const commonConfig = {
  preventDefault: false,
};
const imageConfig = computed<Konva.ImageConfig>(() => ({
  image: imageElem.value || undefined,
  width: stageConfig.width,
  height: stageConfig.height,
  ...commonConfig,
}));
const imageStatus = ref<'ready' | 'pending' | 'error'>('pending');

let resizeObserver: ResizeObserver;
onMounted(() => {
  const img = new Image();
  img.src = props.page.image_url;
  img.onload = () => {
    imageStatus.value = 'ready';
    natural.width = img.naturalWidth;
    natural.height = img.naturalHeight;
    imageElem.value = img;
    updateStageSize();
    const displaySize = { width: stageConfig.width ?? 0, height: stageConfig.height ?? 0 };
    const naturalSize = { width: natural.width ?? 0, height: natural.height ?? 0 };
    tables.splice(0, tables.length, ...convertPageOutputToTableModels(props.page, displaySize, naturalSize));
  };
  img.onerror = () => {
    imageStatus.value = 'error';
  };
  resizeObserver = new ResizeObserver(updateStageSize);
  if (containerRef.value) resizeObserver.observe(containerRef.value);
});

onUnmounted(() => {
  resizeObserver.disconnect();
});

function updateStageSize() {
  if (!containerRef.value || !natural.width) return;

  const newW = containerRef.value.clientWidth;
  const newH = Math.round((natural.height / natural.width) * newW);

  const oldW = stageConfig.width ?? newW;
  const oldH = stageConfig.height ?? newH;

  const scaleX = newW / oldW;
  const scaleY = newH / oldH;

  stageConfig.width = newW;
  stageConfig.height = newH;

  tables.forEach((t) => {
    t.x *= scaleX;
    t.y *= scaleY;
    t.w *= scaleX;
    t.h *= scaleY;

    t.rows.forEach((r) => {
      r.x *= scaleX;
      r.y *= scaleY;
      r.w *= scaleX;
      r.h *= scaleY;

      r.sigs.forEach((s) => {
        s.x *= scaleX;
        s.y *= scaleY;
        s.w *= scaleX;
        s.h *= scaleY;
      });
    });
  });
}

const tables = reactive<TableModel[]>([]);

const { width } = useWindowSize();
const labelsConfig = computed(() => {
  if (width.value < 640) {
    return {
      fontSize: 0,
      padding: 0,
      visible: false,
    };
  } else if (width.value < 1230) {
    return {
      fontSize: 10,
      padding: 3,
      visible: true,
    };
  } else {
    return {
      fontSize: 14,
      padding: 4,
      visible: true,
    };
  }
});
</script>
